import{_ as o,c as i,o as l,ak as t}from"./chunks/framework.CUEecSqI.js";const m=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"sumatra.md","filePath":"sumatra.md","lastUpdated":1753688247000}'),c={name:"sumatra.md"};function d(a,e,r,n,s,u){return l(),i("div",null,e[0]||(e[0]=[t('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>You can <a href="./Customizing-keyboard-shortcuts">customize keyboard shortcuts</a>. Also see <a href="https://support.microsoft.com/en-us/windows/keyboard-shortcuts-in-windows-dcc61a57-8ff0-cffe-9796-cb9706c75eec" target="_blank" rel="noreferrer">standard Windows keyboard shortcuts</a> for controls like tree view or edit fields.</p><p>:columns</p><h3 id="file-menu" tabindex="-1">File menu <a class="header-anchor" href="#file-menu" aria-label="Permalink to &quot;File menu&quot;">​</a></h3><ul><li><code>Ctrl + N</code> - Open a new window</li><li><code>Ctrl + O</code> - Open a file</li><li><code>Ctrl + W</code> - Close current file</li><li><code>Ctrl + S</code> - Save current file as</li><li><code>F2</code> - Rename current file</li><li><code>Ctrl + P</code> - Print</li><li><code>Ctrl + D</code> - Properties</li><li><code>Ctrl + Q</code>, <code>Alt-F4</code> - Quit app</li></ul><h3 id="go-to-menu" tabindex="-1">Go To menu <a class="header-anchor" href="#go-to-menu" aria-label="Permalink to &quot;Go To menu&quot;">​</a></h3><ul><li><code>Right Arrow</code> / <code>Left Arrow</code>- Next / Previous Page <ul><li>scrolls left / right if page width &gt; window width</li></ul></li><li><code>Home</code> - First Page</li><li><code>End</code> - Last Page</li><li><code>Ctrl + G</code> - Go To Page...</li><li><code>Alt + Left Arrow</code> - Back</li><li><code>Alt + Right Arrow</code> - Forward</li><li><code>Ctrl + F</code> - Find...</li></ul><h3 id="favorites-menu" tabindex="-1">Favorites menu <a class="header-anchor" href="#favorites-menu" aria-label="Permalink to &quot;Favorites menu&quot;">​</a></h3><ul><li><code>Ctrl + B</code> - Add current page to favorites</li></ul><h3 id="view-menu" tabindex="-1">View menu <a class="header-anchor" href="#view-menu" aria-label="Permalink to &quot;View menu&quot;">​</a></h3><ul><li><code>Ctrl + 6</code> - Single Page</li><li><code>Ctrl + 7</code> - Facing</li><li><code>Ctrl + 8</code> - Book View</li><li><code>Ctrl + Shift + -</code>, <code>[</code>- Rotate Left (anti-clockwise)</li><li><code>Ctrl + Shift + +</code>, <code>]</code>- Rotate Right (clockwise)</li><li><code>F5</code> - Enter / Exit Presentation</li><li><code>F11</code> - Enter / Exit Full Screen</li><li><code>F12</code> - Show / Hide Bookmarks</li><li><code>F8</code> - Show / Hide Toolbar</li><li><code>Ctrl + A</code> - Select All</li><li><code>Ctrl + C</code> - Copy Selection</li></ul><h3 id="zoom-menu" tabindex="-1">Zoom menu <a class="header-anchor" href="#zoom-menu" aria-label="Permalink to &quot;Zoom menu&quot;">​</a></h3><ul><li><code>Ctrl + 0</code> - Fit Page</li><li><code>Ctrl + 1</code> - Actual Size</li><li><code>Ctrl + 2</code> - Fit Width</li><li><code>Ctrl + 3</code> - Fit Content</li><li><code>Ctrl + Y</code> - Custom Zoom...</li></ul><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><code>j</code> / <code>k</code> - Scroll up / down by line</li><li><code>h</code> / <code>l</code> - Scroll left / right</li><li><code>Up</code> / <code>Down</code> - Scroll up/down by line</li><li><code>Shift + Left</code> / <code>Shift + Right</code>- Scroll left /right faster</li><li><code>space</code> - Scroll by screen</li><li><code>Shift + space</code> - Scroll back by screen</li><li><code>n</code> / <code>p</code> - Next / previous page</li><li><code>Page Down</code> / <code>Page Up</code> - Next / previous page</li><li><code>Ctrl + Down</code> / <code>Ctrl + Up</code> - Next / previous page</li><li><code>Alt + Left</code> - Go back</li><li><code>Alt + Right</code> - Go forward</li><li><code>Ctrl + G</code> - Go to page</li><li><code>g</code> - Go to page</li><li><code>Home</code> - Go to first page</li><li><code>End</code> - Go to last page</li><li><code>b</code> - Flip a page in book mode</li><li><code>Ctrl + Shift + Right</code> - Open next document in the directory</li><li><code>Ctrl + Shift + Left</code> - Open previous document in the directory</li></ul><h3 id="viewing-state" tabindex="-1">Viewing state <a class="header-anchor" href="#viewing-state" aria-label="Permalink to &quot;Viewing state&quot;">​</a></h3><ul><li><code>+</code> / <code>-</code> - zoom in/out</li><li><code>Ctrl + scroll wheel</code> - zoom in/out</li><li><code>z</code> - toggle zoom between Fit Page, Fit Width, Fit Content</li><li><code>c</code> - toggle between continuous/non-continuous mode</li><li><code>Ctrl + Shift + -</code> - rotate left</li><li><code>/</code> on numeric keypad - rotate left</li><li><code>Ctrl + Shift + +</code> - rotate right</li><li><code>*</code> on numeric keypad - rotate left</li><li><code>F12</code> - show/hide bookmarks (table of contents)</li><li><code>F6</code> - switch focus between bookmarks window and main window</li><li><code>Ctrl + L</code>, <code>F5</code>, <code>Shift + F11</code>- Enter / exit presentation mode (minimal full screen mode)</li><li><code>F11</code>, <code>Ctrl + Shift + L</code>, <code>f</code> - Enter / Exit full screen mode</li><li><code>ESC</code> - exit full screen or presentation mode</li><li>mouse double click - exit full screen or presentation mode</li><li><code>i</code> - invert colors in the document</li><li><code>Shift + i</code> - show current page number</li><li><code>m</code> - show cursor position in document coordinates</li><li><code>F8</code> - show/hide toolbar</li><li><code>F9</code> - show/hide menu</li><li><code>w</code> - in presentation mode, make whole screen white</li><li><code>.</code> - in presentation mode, make whole screen black</li></ul><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ul><li><code>Ctrl + O</code> - Open a new document</li><li><code>Ctrl + W</code> - Close current document</li><li><code>Ctrl + F4</code> - Also close current document</li><li><code>Ctrl + S</code> - Save current document as...</li><li><code>Ctrl + Shift + S</code> - Create a link to current document</li><li><code>Ctrl + P</code> - Print</li><li><code>F2</code> - Rename file and reopen with new name</li><li><code>Ctrl + Shift + N</code> - Open current document in new window</li><li><code>r</code> - Reload document</li><li><code>Ctrl + F</code> - Find text</li><li><code>/</code> - Find text</li><li><code>F3</code> - Find next</li><li><code>Shift + F3</code> - Find previous</li><li><code>Alt + F4</code> - Close window (and all documents in it). Quit app if last window.</li><li><code>q</code> - Close current document (tab). Close window if last tab. Quit app if last window.</li><li><code>Ctrl + Q</code> - Quit app (close all windows and opened documents)</li><li><code>Ctrl + Left Mouse</code> - Select area (can then use with copy, print or +/- zoom)</li><li><code>Ctrl + B</code> - Add current page to favorites</li><li><code>Right Mouse</code> - Grab and pan page in any direction</li><li><code>Alt + Scroll Wheel</code> - Increase vertical scroll wheel steps (faster)</li><li><code>Shift + Scroll Wheel</code> - Pan horizontally with scroll wheel</li><li><code>Ctrl + Y</code> - Show dropdown zoom control</li><li><code>F1</code> - Show documentation / manual</li></ul><h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><ul><li><code>Ctrl + Tab</code> - go to next tab</li><li><code>Ctrl + Shift + Tab</code> - go to previous tab</li><li><code>Alt + 1</code> - go to tab 1. Use <code>Alt + 2</code>, etc. up to <code>Alt + 8</code></li><li><code>Alt + 9</code> - go to last tab</li></ul><h3 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h3><p><strong>Ver 3.3+</strong>, some in <strong>ver 3.4+</strong>:</p><ul><li><code>a</code> - create highlight annotation from selected text</li><li><code>A</code> - like <code>a</code> plus opens annotation editor</li><li><code>u</code> - create underline annotation from selected text</li><li><code>Delete</code> - delete annotation under mouse cursor</li><li><code>Ctrl-Shift-S</code> - save annotations to current PDF file</li></ul><p>:columns</p>',25)]))}const f=o(c,[["render",d]]);export{m as __pageData,f as default};
